if(g.kind==='regionMove'||g.kind==='regionResize'){const candidate=g.candidate;const original=g.original||world.regions.find(r=>r.id===candidate?.id);const allowed=candidate&&(g.kind==='regionMove'?regionMoveValid(candidate,original):validRegion(candidate));if(allowed){checkpoint();if(g.kind==='regionMove'&&carryingRegion())moveRegionContents(original,candidate);world.regions=world.regions.map(r=>r.id===candidate.id?candidate:r);changed()}else if(candidate)toast('目标区域或方块被占用，请调整位置或开启对应覆盖开关');draw();return}
