let performanceMode=false,qualitySettings=null;
function optimizeRendering(){
 if(gesture)endGesture();
 performanceMode=!performanceMode;
 if(performanceMode){
  qualitySettings={grid:$('grid').checked,regions:$('showRegions').checked,empty:$('showEmptyRegions').checked};
  $('grid').checked=false;$('showRegions').checked=false;$('showEmptyRegions').checked=false;
 }else if(qualitySettings){
  $('grid').checked=qualitySettings.grid;$('showRegions').checked=qualitySettings.regions;$('showEmptyRegions').checked=qualitySettings.empty;
 }
 resetTerrainIndex();terrainRevision++;regionGeometry=new WeakMap();regionOccupancy=new WeakMap();
 const usedImages=new Set(world.types.map(t=>t.image).filter(Boolean));
 for(const source of Object.values(world.artAssets||{}))usedImages.add(source);
 for(const source of tileImages.keys())if(!usedImages.has(source))tileImages.delete(source);
 $('optimize').textContent=performanceMode?'恢复完整显示':'性能优化';
 $('optimize').classList.toggle('active',performanceMode);
 world.editorOptions=readSceneDisplay();world.editorPerformance={enabled:performanceMode,restore:qualitySettings?{...qualitySettings}:null};persist();draw();toast(performanceMode?'已重建缓存并启用轻量显示，可再次点击恢复':'已恢复完整显示');
}
