 if(!confirm('将场景“'+world.title+'”移入回收站？之后可以恢复。'))return;
 if(gesture)endGesture();
 try{stash();archiveSceneToTrash(mapId,world)}catch(error){storageFailure(error);return}
 roomDetail=null;roomOverviewView=null;const deletedId=mapId,index=maps.findIndex(m=>m.id===deletedId);
 removedMapIds.add(deletedId);pendingDeletionJournal.add(deletedId);dirtyMapIds.delete(deletedId);maps.splice(index,1);mapStates.delete(deletedId);pendingHistory=null;resetTerrainIndex();
 if(!maps.length){const id=uid('map');maps.push({id,world:normalize({title:'未命名世界',types:clone(world.types),cells:{},regions:[],groups:[],members:{}})})}
 const next=maps[Math.min(index,maps.length-1)];mapId=next.id;world=next.world;
 const state=mapStates.get(mapId);managedRoomSelection=state?.managedRoomSelection||null;roomDetail=state?.roomDetail||null;roomOverviewView=state?.roomOverviewView||null;applySceneDisplay();history=state?.history||[];future=state?.future||[];
 active=state?.active||world.types[0].id;activeGroup=state?.activeGroup??world.activeGroup??'';
 selected.clear();selectedRegion=null;gesture=null;focusedCameraRoom=null;cameraPreviewMode=false;$('cameraPreview').textContent='键盘镜头预览';
 if(state)view={...state.view};else fit();
 changed();try{saveLibrary()}catch{toast('本机保存失败，请立即备份全部地图');return}
